  pink: "#FF64B8",
  lightPink: "#FEF3FF",
  mutedPurple: "#9D829F",
  darkPurple: "#694D6B",
  orange: "#FF8C42",
  cyan: "#42E8FF",
  green: "#42FF8C",
  bg: "#12091A",
