// ─── SCENE 1 ───
const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const PARTICLES = [
    { x: 18, delay: 0, symbol: "#fitness", size: 28, opacity: 0.5 },
    { x: 32, delay: 4, symbol: "1.2M", size: 38, opacity: 0.8 },
    { x: 60, delay: 2, symbol: "#pilates", size: 32, opacity: 0.6 },
    { x: 65, delay: 6, symbol: "847K", size: 26, opacity: 0.45 },
    { x: 78, delay: 1, symbol: "#yoga", size: 34, opacity: 0.7 },
    { x: 12, delay: 8, symbol: "JSON", size: 22, opacity: 0.35 },
    { x: 44, delay: 3, symbol: "↗", size: 52, opacity: 0.6 },
    { x: 88, delay: 5, symbol: "#workout", size: 24, opacity: 0.45 },
    { x: 25, delay: 10, symbol: "92K", size: 30, opacity: 0.6 },
    { x: 72, delay: 7, symbol: "#health", size: 28, opacity: 0.5 },
  ];

  const centralProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const ringProgress = spring({ frame, fps, delay: 20, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill>
        {PARTICLES.map((p, i) => {
          const prog = spring({ frame, fps, delay: p.delay, config: { damping: 200 } });
          const floatY = interpolate(frame, [0, 120], [0, -30], { extrapolateRight: "clamp" });
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: `${p.x}%`,
                top: `${25 + ((i * 17) % 50)}%`,
                opacity: prog * p.opacity,
                transform: `translateY(${interpolate(prog, [0, 1], [40, 0]) + floatY}px)`,
                fontSize: p.size,
                fontWeight: 700,
                color: i % 3 === 0 ? COLORS.pink : i % 3 === 1 ? COLORS.cyan : "rgba(255,255,255,0.6)",
                fontFamily: "'Inter', sans-serif",
                whiteSpace: "nowrap",
              }}
            >
              {p.symbol}
            </div>
          );
        })}

        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(-50%, -50%) scale(${interpolate(centralProgress, [0, 1], [0.3, 1])})`,
            opacity: centralProgress,
          }}
        >
          <svg width="280" height="280" viewBox="0 0 280 280">
            <circle cx="140" cy="140" r="110" stroke={COLORS.pink} strokeWidth="1.5" fill="none"
              opacity={interpolate(ringProgress, [0, 1], [0, 0.2])} />
            <circle cx="140" cy="140" r="70" stroke={COLORS.pink} strokeWidth="2.5"
              fill={`${COLORS.pink}15`} opacity={centralProgress} />
            <circle cx="140" cy="140" r="28" fill={COLORS.pink}
              opacity={interpolate(centralProgress, [0, 1], [0, 0.6])} />
            {Array.from({ length: 12 }).map((_, i) => {
              const angle = (i / 12) * Math.PI * 2 - Math.PI / 2;
              const x1 = 140 + Math.cos(angle) * 78;
              const y1 = 140 + Math.sin(angle) * 78;
              const x2 = 140 + Math.cos(angle) * 92;
              const y2 = 140 + Math.sin(angle) * 92;
              const tickProg = spring({ frame, fps, delay: 20 + i * 3, config: { damping: 200 } });
              return (
                <line key={i} x1={x1} y1={y1} x2={x2} y2={y2}
                  stroke={COLORS.pink} strokeWidth="1.5" opacity={tickProg * 0.7} strokeLinecap="round" />
              );
            })}
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

