const Scene5: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const ring1 = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const ring2 = spring({ frame, fps, delay: 22, config: { damping: 200 } });
  const ring3 = spring({ frame, fps, delay: 39, config: { damping: 200 } });
  const label1 = spring({ frame, fps, delay: 30, config: { damping: 200 } });
  const label2 = spring({ frame, fps, delay: 47, config: { damping: 200 } });
  const label3 = spring({ frame, fps, delay: 64, config: { damping: 200 } });
  const dotProgress = spring({ frame, fps, delay: 70, config: { damping: 200 } });

  const pulse = interpolate(frame % 50, [0, 25, 50], [1, 1.012, 1], { extrapolateRight: "clamp" });

  // 2x: canvas 1720x1720, center 860,860, radii 760/500/260
  const W = 1720;
  const CX = 860;
  const CY = 860;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "relative", width: W, height: W }}>
          <svg width={W} height={W} viewBox={`0 0 ${W} ${W}`} style={{ position: "absolute", top: 0, left: 0 }}>
            {/* Outer ring — high volume */}
            <circle
              cx={CX} cy={CY}
              r={interpolate(ring1, [0, 1], [0, 760]) * pulse}
              fill={`${COLORS.pink}08`} stroke={COLORS.pink} strokeWidth="2.5"
              opacity={ring1 * 0.6}
            />
            {/* Mid ring */}
            <circle
              cx={CX} cy={CY}
              r={interpolate(ring2, [0, 1], [0, 500])}
              fill={`${COLORS.cyan}10`} stroke={COLORS.cyan} strokeWidth="3"
              opacity={ring2 * 0.7}
            />
            {/* Niche ring */}
            <circle
              cx={CX} cy={CY}
              r={interpolate(ring3, [0, 1], [0, 260])}
              fill={`${COLORS.green}18`} stroke={COLORS.green} strokeWidth="4"
              opacity={ring3 * 0.9}
            />
            {/* Center dot */}
            <circle cx={CX} cy={CY} r={interpolate(dotProgress, [0, 1], [0, 28])} fill={COLORS.green} opacity={dotProgress} />
            {/* Guide lines */}
            {[0, 90, 180, 270].map((deg, i) => {
              const rad = (deg * Math.PI) / 180;
              return (
                <line key={i}
                  x1={CX} y1={CY}
                  x2={CX + Math.cos(rad) * 790 * ring1}
                  y2={CY + Math.sin(rad) * 790 * ring1}
                  stroke="rgba(255,255,255,0.06)" strokeWidth="1.5" strokeDasharray="8 14"
                />
              );
            })}
          </svg>

          {/* HIGH VOLUME label — right side */}
          <div style={{
            position: "absolute",
            top: CY - 30,
            left: CX + 790,
            transform: `translateX(${interpolate(label1, [0, 1], [40, 0])}px)`,
            opacity: label1,
          }}>
            <div style={{ fontSize: 56, fontWeight: 700, color: COLORS.pink, whiteSpace: "nowrap" }}>HIGH VOLUME</div>
            <div style={{ fontSize: 40, color: "rgba(255,255,255,0.35)", whiteSpace: "nowrap" }}>Large audiences</div>
          </div>

          {/* MID label */}
          <div style={{
            position: "absolute",
            top: CY - 280,
            left: CX + 520,
            transform: `translateX(${interpolate(label2, [0, 1], [30, 0])}px)`,
            opacity: label2,
          }}>
            <div style={{ fontSize: 52, fontWeight: 700, color: COLORS.cyan, whiteSpace: "nowrap" }}>MID VOLUME</div>
            <div style={{ fontSize: 38, color: "rgba(255,255,255,0.35)", whiteSpace: "nowrap" }}>Top posts</div>
          </div>

          {/* NICHE label */}
          <div style={{
            position: "absolute",
            top: CY - 200,
            left: CX + 280,
            transform: `translateX(${interpolate(label3, [0, 1], [24, 0])}px)`,
            opacity: label3,
          }}>
            <div style={{ fontSize: 48, fontWeight: 700, color: COLORS.green, whiteSpace: "nowrap" }}>NICHE</div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

