  const titleProg   = spring({ frame, fps, delay: 5,   config: { damping: 200 } });
  const circle1Prog = spring({ frame, fps, delay: 25,  config: { damping: 200 } });
  const circle2Prog = spring({ frame, fps, delay: 40,  config: { damping: 200 } });
  const overlapProg = spring({ frame, fps, delay: 65,  config: { damping: 200 } });
  const insightProg = spring({ frame, fps, delay: 155, config: { damping: 200 } });

  // 2x scale: SVG is 2400x900, circles centered at x=680 and x=1520, y=380
  const SVG_W = 2400;
  const SVG_H = 900;
  const C1X = 680;
  const C2X = 1520;
  const CY = 380;
  const RX = 480;
  const RY = 320;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 60,
          gap: 60,
        }}
      >
        {/* Title */}
        <div
          style={{
            opacity: titleProg,
            transform: `translateY(${interpolate(titleProg, [0, 1], [-24, 0])}px)`,
            fontSize: 56,
            fontWeight: 600,
            color: "rgba(255,255,255,0.35)",
            letterSpacing: "0.15em",
            textTransform: "uppercase" as const,
          }}
        >
          Co-occurrence data
        </div>

        {/* Venn diagram */}
        <div style={{ position: "relative", width: SVG_W, height: SVG_H }}>
          <svg
            width={SVG_W} height={SVG_H}
            viewBox={`0 0 ${SVG_W} ${SVG_H}`}
            style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}
          >
            {/* Connecting dashed lines to adjacent chips */}
            {ADJACENT.map((chip, i) => {
              const lineProg = spring({ frame, fps, delay: 120 + i * 14, config: { damping: 200 } });
              const overlapCX = (C1X + C2X) / 2;
              return (
                <line
                  key={i}
                  x1={overlapCX} y1={CY}
