// ─── SCENE 8 — 2x bigger ───
const Scene8: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const lineProg  = spring({ frame, fps, delay: 5,  config: { damping: 200 } });
  const dotProg   = spring({ frame, fps, delay: 30, config: { damping: 200 } });
  const labelProg = spring({ frame, fps, delay: 45, config: { damping: 200 } });
  const arrowProg = spring({ frame, fps, delay: 60, config: { damping: 200 } });
  const textProg  = spring({ frame, fps, delay: 80, config: { damping: 200 } });

  // 2x: curve spans 2400px wide, 800px tall
  const CURVE_W = 2400;
  const CURVE_H = 800;

  const CURVE_POINTS = Array.from({ length: 80 }, (_, i) => {
    const t = i / 79;
    const x = t * CURVE_W;
    const y = CURVE_H - 60 - Math.pow(t, 2.5) * (CURVE_H - 100);
    return { x, y };
  });

  const drawLen = interpolate(lineProg, [0, 1], [0, 80]);
  const visiblePoints = CURVE_POINTS.slice(0, Math.max(2, Math.round(drawLen)));
  const pathD = visiblePoints.reduce((acc, pt, i) => {
    return acc + (i === 0 ? `M${pt.x},${pt.y}` : ` L${pt.x},${pt.y}`);
  }, "");

  const markerT = 0.35;
  const markerX = markerT * CURVE_W;
  const markerY = CURVE_H - 60 - Math.pow(markerT, 2.5) * (CURVE_H - 100);
  const peakX = CURVE_W;
  const peakY = 60;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "relative", width: CURVE_W + 160, height: CURVE_H + 160 }}>
          <svg
            width={CURVE_W + 160}
            height={CURVE_H + 160}
            viewBox={`-80 -60 ${CURVE_W + 160} ${CURVE_H + 160}`}
            style={{ overflow: "visible" }}
          >
            <defs>
              <linearGradient id="growthGrad2" x1="0" y1="0" x2="1" y2="0" gradientUnits="objectBoundingBox">
                <stop offset="0%" stopColor={COLORS.cyan} />
                <stop offset="60%" stopColor={COLORS.pink} />
                <stop offset="100%" stopColor={COLORS.green} />
              </linearGradient>
              <linearGradient id="fillGrad2" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={COLORS.pink} stopOpacity="0.12" />
                <stop offset="100%" stopColor={COLORS.pink} stopOpacity="0" />
              </linearGradient>
            </defs>

            {/* Horizontal guide lines */}
            {[0, 200, 400, 600, 800].map((y) => (
              <line key={y} x1="0" y1={y} x2={CURVE_W} y2={y}
                stroke="rgba(255,255,255,0.04)" strokeWidth="1.5" />
            ))}

            {/* Area fill */}
            {pathD && (
              <path
                d={`${pathD} L${visiblePoints[visiblePoints.length - 1].x},${CURVE_H} L0,${CURVE_H} Z`}
                fill="url(#fillGrad2)"
              />
            )}
            {/* Growth curve */}
            {pathD && (
              <path d={pathD} stroke="url(#growthGrad2)" strokeWidth="7"
                fill="none" strokeLinecap="round" strokeLinejoin="round" />
            )}

            {/* "You are here" marker */}
            <circle cx={markerX} cy={markerY}
              r={interpolate(dotProg, [0, 1], [0, 26])}
              fill={COLORS.pink} opacity={dotProg} />
            <circle cx={markerX} cy={markerY}
              r={interpolate(dotProg, [0, 1], [0, 52])}
              fill="none" stroke={COLORS.pink} strokeWidth="2.5"
              opacity={dotProg * 0.4} />

            {/* Peak dot */}
            <circle cx={peakX} cy={peakY}
              r={interpolate(arrowProg, [0, 1], [0, 20])}
              fill={COLORS.green} opacity={arrowProg * 0.8} />

            {/* Dashed line from marker to peak */}
            <line
              x1={markerX} y1={markerY}
              x2={interpolate(arrowProg, [0, 1], [markerX, peakX])}
              y2={interpolate(arrowProg, [0, 1], [markerY, peakY])}
              stroke={COLORS.green} strokeWidth="2.5"
              strokeDasharray="14 18" opacity={arrowProg * 0.5} />
          </svg>

          {/* "you are here" label */}
          <div style={{
            position: "absolute",
            left: markerX - 100,
            top: markerY - 100,
            opacity: labelProg,
            transform: `translateY(${interpolate(labelProg, [0, 1], [20, 0])}px)`,
            textAlign: "center",
          }}>
            <div style={{ fontSize: 48, fontWeight: 700, color: COLORS.pink, whiteSpace: "nowrap" }}>you are here</div>
          </div>

          {/* "peak" label */}
          <div style={{
            position: "absolute",
            left: peakX - 60,
            top: peakY - 90,
            opacity: arrowProg,
            transform: `translateY(${interpolate(arrowProg, [0, 1], [20, 0])}px)`,
            textAlign: "center",
          }}>
            <div style={{ fontSize: 48, fontWeight: 700, color: COLORS.green }}>peak</div>
          </div>

          {/* Bottom text */}
          <div style={{
            position: "absolute",
            bottom: -20,
            left: "50%",
            transform: `translateX(-50%) translateY(${interpolate(textProg, [0, 1], [30, 0])}px)`,
            opacity: textProg,
            fontSize: 60,
            fontWeight: 700,
            color: "rgba(255,255,255,0.7)",
            whiteSpace: "nowrap" as const,
            textAlign: "center",
          }}>
            Get in{" "}
            <span style={{ color: COLORS.pink }}>before it peaks</span>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

